  const kpiCell = sheet.getCell("A3");
  kpiCell.value = `Total Invoices: ${invoices.length}  |  Total Taxable: \u20B9${totalTxval.toLocaleString("en-IN", { minimumFractionDigits: 2 })}  |  Total Tax (ITC): \u20B9${totalTax.toLocaleString("en-IN", { minimumFractionDigits: 2 })}`;
  kpiCell.font = { name: "Segoe UI", size: 10, bold: true, color: { argb: "FF047857" } };
  kpiCell.fill = CARD_FILL;
  kpiCell.alignment = { horizontal: "left", vertical: "middle" };
